   * Re-enters dependency tracking for a synchronous block after an `await`.
   * Signals read inside the callback register on this reaction and accumulate
   * into the current run, so an async reaction can depend on values it reads past
   * its first `await`.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reaction#track track}
   * @param callback - Synchronous function whose signal reads should be tracked
   * @returns The callback's return value
   */
  track<T>(callback: () => T): T;

  /**
   * Marks the reaction invalid and schedules it to run again on the next flush.
   * Called automatically when a dependency changes. Calling it with no arguments
   * re-runs the reaction without any signal having changed.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reaction#invalidate invalidate}
   * @param context - Optional metadata about what triggered the invalidation
   */
  invalidate(context?: Record<string, any>): void;

  /**
   * Permanently stops the reaction. It unsubscribes from all dependencies, fires
   * its cleanups, and will no longer respond to changes. Idempotent.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reaction#stop stop}
   */
  stop(): void;
}

/**
 * Configuration options for creating a new ReactiveObject instance.
 * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reactive-object#options ReactiveObject Options}
 */
export interface ReactiveObjectOptions {
  /**
   * Value-protection preset controlling how the backing object is guarded against
   * outside mutation. `'reference'` (default) reads and stores by reference.
   * `'clone'` returns defensive copies on read and clones inbound objects on
   * `set` and `replace`. `'none'` treats every `set()` as a change (event-stream
   * semantics).
   * @default 'reference'
   */
  safety?: 'clone' | 'reference' | 'none';

  /**
   * Determines whether a candidate value differs from the value currently at a
   * path. A write notifies a path's readers only when this returns `false`.
   * @param oldValue - The current value at the path
   * @param newValue - The candidate value
   */
  equality?: (oldValue: any, newValue: any) => boolean;

  /**
   * Produces a copy of a value, used to insulate reads and inbound objects when
   * `safety` is `'clone'`.
   * @param value - The value to copy
   */
  clone?: <V>(value: V) => V;

  /**
   * Seeds the monotonic change counter, so it can start aligned with an
   * external store's revision.
   * @default 0
   */
  version?: number;
}

/**
 * Fine-grained reactivity over a plain object, at the granularity of a PATH. A
 * reader of one path is woken only when the value at that path changes, where a
 * single Signal holding an object would wake every reader on any change.
 *
 * Addressed by the `@semantic-ui/utils` path grammar: dotted keys, positional
 * `[i]` indices, and keyed `[#id]` array segments. Reactivity is keyed by the
 * literal path string, so an element must be addressed consistently: a reader of
 * `todos[#a].done` is not woken by a positional write to `todos[0].done` that
 * hits the same element.
 *
 * Create one with the `reactiveObject()` factory or `new ReactiveObject()`.
 * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reactive-object ReactiveObject Documentation}
 */
export class ReactiveObject {
  /**
   * Default equality (deep) used by instances that don't supply their own. Set
   * this to change the default for instances created afterward.
   */
  static equality: (oldValue: any, newValue: any) => boolean;

  /**
   * Default clone used by instances that don't supply their own.
   */
  static clone: <V>(value: V) => V;

  /**
   * Default safety preset for new instances.
   * @default 'reference'
   */
  static safety: 'clone' | 'reference' | 'none';

  /**
   * Creates a new ReactiveObject backing a plain object.
   * @param initialValue - The initial backing object (defaults to `{}`)
   * @param options - Configuration for protection and equality
   */
  constructor(initialValue?: object, options?: ReactiveObjectOptions);

  /**
   * Tracked read. Subscribes the current reaction to this path alone, so a later
   * write to a disjoint path will not re-fire it.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reactive-object#get get}
   * @param path - The path to read
   */
  get(path: string): any;

  /**
   * Untracked read. With a path the value there, without one the whole backing
   * object. Subscribes to nothing.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reactive-object#peek peek}
   * @param path - Optional path to read
   */
  peek(path?: string): any;

  /**
   * Whether any live reaction subscribes to a path, or to the whole object when
   * no path is given.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reactive-object#hasdependents hasDependents}
   * @param path - Optional path to check
   */
  hasDependents(path?: string): boolean;

  /**
   * Subscribes the current reaction to a path without reading its value, the
   * path-scoped twin of `Signal.depend()`. Use it when a reaction should re-run
   * on a change but reads the value from elsewhere.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reactive-object#depend depend}
   * @param path - The path to subscribe to
   */
  depend(path: string): void;

  /**
   * Tracked existence check. Distinguishes a stored `undefined` from a missing
   * path, and wakes through the same cell as `get()` when the key is removed or
   * re-added.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reactive-object#has has}
   * @param path - The path to test
   * @returns Whether the path is present
   */
  has(path: string): boolean;

  /**
   * Returns the live stored reference with no dependency and no clone
   * protection, even under `safety: 'clone'` where `peek()` still copies. With
   * no path, the whole backing object. Mutating the result bypasses change
   * detection.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reactive-object#raw raw}
   * @param path - Optional path to read
   * @returns The live stored value
   */
  raw(path?: string): any;

  /**
   * Tracked, detached deep copy at a path: mutating the copy never touches the
   * stored value, and the reader still re-runs on a later write. Always copies,
   * even under `safety: 'reference'`. With no path, clones the whole object
   * untracked, mirroring `peek()`'s no-path form.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reactive-object#clone clone}
   * @param path - Optional path to copy
   * @returns A detached copy of the value
   */
  clone(path?: string): any;

  /**
   * Monotonic change counter, the `Signal.version` twin. Bumps on every
   * wake-causing write: a changed `set()`, a successful `remove()`, and every
   * `replace()`, `clear()`, and `notify()`. An equality-gated no-op `set()`
   * leaves it unchanged. Reading it registers no dependency. Seed it with the
   * `version` option, or assign it to realign with an external store's revision.
   */
  version: number;

  /**
   * Single-path write, equality-gated. Wakes readers of this path, of its
   * ancestors, and of any descendant whose resolved value changed. A same-value
   * write, or one the backing object drops (a field under an absent keyed
   * element), wakes nobody and returns `false`.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reactive-object#set set}
   * @param path - The path to write
   * @param value - The value to set
   * @returns Whether the write changed anything
   */
  set(path: string, value: any): boolean;

  /**
   * Force-wakes a path after an in-place mutation, the `Signal.notify()` twin.
   * Wakes the exact path, its ancestors, and every descendant under it (with no
   * before image to diff, the whole subtree fires). Bumps `version`.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reactive-object#notify notify}
   * @param path - The path whose subtree changed in place
   */
  notify(path: string): void;

  /**
   * Removes a path so the key leaves the object. It reads back absent, not
   * undefined-valued. The guard keys on presence, so a key holding a stored
   * `undefined` is removable, and only an already-absent path is a no-op.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reactive-object#remove remove}
   * @param path - The path to remove
   * @returns Whether the removal changed anything
   */
  remove(path: string): boolean;

  /**
   * Bulk inbound swap: replaces the whole backing object and reseeds every live
   * reader against the new object, waking only paths whose value changed,
   * including deep readers under a wholesale-replaced subtree. Dead cells are
   * evicted in the pass.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reactive-object#replace replace}
   * @param nextObject - The replacement backing object
   */
  replace(nextObject: object): void;

  /**
   * Replaces the backing object with an empty one.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reactive-object#clear clear}
   */
  clear(): void;

  /**
   * Sweeps cells nobody subscribes to. `replace` and subtree writes sweep as they
   * go. This is the explicit hook for an instance driven only by `set`/`remove`.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reactive-object#prune prune}
   */
  prune(): void;

  /**
   * Drops every cell. Live subscribers stop receiving wakes, future reads mint
   * fresh cells.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/reactive-object#stop stop}
   */
  stop(): void;
}

import type { Reaction } from './reaction.js';
import type { Signal, SignalOptions } from './signal.js';

/**
 * Configuration options for creating a new Resource instance. Extends
 * `SignalOptions`, so a Resource carries the same `equality` (which becomes the
 * refresh dedup), `safety`, `id`, and `context` configuration as any Signal.
 * @see {@link https://next.semantic-ui.com/docs/api/reactivity/resource#options Resource Options}
 */
export interface ResourceOptions<T> extends SignalOptions<T> {
  /**
   * The value `get()` returns before the first fetch settles. Defaults to
   * `undefined`.
   */
  initialValue?: T;

  /**
   * Called when a fetch rejects, after the `error` face is set and the faces
   * settle. Superseded runs never report. For value-only consumers that would
   * otherwise miss rejections landing silently in the `error` face.
   */
  onError?: (error: unknown) => void;

  /**
   * How a refetch behaves when a tracked read or `refresh()` fires while a run
   * is in flight. `'latest'` (the default) serializes runs: the in-flight run
   * aborts through `computation.abortSignal` and the refetch coalesces into one
   * re-run after it settles, so at most one fetch is ever in flight. `'overlap'`
   * starts every fetch immediately and lets the newest run's settle win, for
   * fetchers that cannot cooperate with cancellation. Overlap costs concurrent
   * fetches under churn, and its runs are invisible to `settled()` because the
   * backing reaction stays synchronous. Defaults to `'latest'`.
   */
  concurrency?: 'latest' | 'overlap';
}

/**
 * A Resource is a Signal whose value an async fetcher produces. The fetcher runs
 * as an async reaction: signals it reads before its first `await` are tracked
 * and re-fire the fetch when they change. By default runs never overlap and a
 * superseded run aborts through `computation.abortSignal` (latest-wins), which
 * the `concurrency` option can relax to overlapping runs. The stored value
 * holds last-good through a refresh and through a rejection. Fetch status lives
 * in the separate `loading`, `error`, and `settled` faces, each reactive on its
 * own.
 *
 * Create one with the `resource()` factory or `new Resource()` — both are
 * supported. It is a Signal, so `get()`, `peek()`, `getItem()`, equality dedup,
 * and the rest of the Signal surface apply.
 * @see {@link https://next.semantic-ui.com/docs/api/reactivity/resource Resource Documentation}
 */
export class Resource<T> extends Signal<T> {
  /**
   * Creates a Resource backed by a fetcher. The fetcher runs immediately as an
   * async reaction and receives the backing Reaction as its argument. A promise
   * return holds the resource in flight until it settles, a synchronous return
   * settles at once.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/resource#resource constructor}
   * @param fetcher - Produces the value, receiving the backing computation
   * @param options - Configuration for the resource's behavior
   */
  constructor(fetcher: (computation: Reaction) => T | Promise<T>, options?: ResourceOptions<T>);

  /**
   * `true` while a fetch is in flight, `false` otherwise. A synchronous fetcher
   * return never flips it. Reads re-run only at the transition, so a skeleton
   * state is `loading && !settled` and a refresh shimmer is `loading && settled`.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/resource#loading loading}
   */
  readonly loading: boolean;

  /**
   * The error from the most recent rejected fetch, cleared on the next fulfilled
   * settle and `undefined` otherwise. Reads re-run only at transitions. A
   * rejection never reaches `console.error` or surfaces as an unhandled rejection.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/resource#error error}
   */
  readonly error: unknown;

  /**
   * Latches `true` after the first completed fetch (fulfilled or rejected) and
   * stays `true` for the resource's life. Reads re-run once, at that first settle.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/resource#settled settled}
   */
  readonly settled: boolean;

  /**
   * Re-fires the fetcher by invalidating the backing reaction. The stored value
   * holds until the refresh settles.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/resource#refresh refresh}
   */
  refresh(): void;

  /**
   * Permanently stops the resource. Re-fires end, the loading face clears, and
   * the last value stays readable. A resource created inside a reaction stops
   * with its parent, and an unreferenced handle self-stops. Idempotent.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/resource#stop stop}
   */
  stop(): void;
}

import type { Reaction } from './reaction.js';

/**
 * Manages scheduling and execution of reactive updates, batching reactions and
 * draining them on a microtask. Application code uses the free functions
 * `flush()`, `scheduleFlush()`, `afterFlush()`, and `settled()` rather than the
 * class directly.
 * @see {@link https://next.semantic-ui.com/docs/api/reactivity/scheduler Scheduler Documentation}
 *
 * @internal Primarily used internally by the reactivity system.
 */
export class Scheduler {
  /** The reaction currently executing, if any. */
  static current: Reaction | null;

  /** Reactions queued to run on the next flush. */
  static pendingReactions: Set<Reaction>;

  /** Known-async reactions whose deferred re-runs start at the flush drain point. */
  static pendingAsyncReactions: Set<Reaction>;

  /** Async reactions with a run currently in flight. */
  static settlingReactions: Set<Reaction>;

  /** Callbacks queued to run after the next flush drains. */
  static afterFlushCallbacks: Array<() => void>;

  /** Deferred backing the pending `settled()` promise, or null when nobody waits. */
  static settledDeferred: { promise: Promise<void>; resolve: () => void; } | null;

  /** Whether a flush is scheduled on the microtask queue. */
  static isFlushScheduled: boolean;

  /** Whether a flush is currently draining. */
  static isFlushing: boolean;

  /** Iteration cap before `flush` declares a reactive cycle and bails. */
  static maxFlushIterations: number;

  /**
   * Queues a reaction to run on the next flush.
   * @internal
   * @param reaction - The reaction to schedule
   */
  static scheduleReaction(reaction: Reaction): void;

  /**
   * Schedules a flush on the next microtask. Idempotent.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/flushing#scheduleflush scheduleFlush}
   */
  static scheduleFlush(): void;

  /**
   * Synchronously drains all pending reactions, async run starts, and after-flush
   * callbacks. Does not wait for in-flight async runs. Use `settled()` for full
   * quiescence. Caps at `maxFlushIterations` to break reactive cycles, logging an
   * error and clearing the queues if the cap is exceeded.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/flushing#flush flush}
   */
  static flush(): void;

  /**
   * Clears every queue and logs an error when a flush exceeds
   * `maxFlushIterations`, breaking a runaway reactive cycle.
   * @internal
   */
  static reportCycle(): void;

  /**
   * Registers a callback to run after the next flush drains.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/flushing#afterflush afterFlush}
   * @param callback - Function to run after updates are processed
   */
  static afterFlush(callback: () => void): void;

  /**
   * Whether no reactions are pending, in flight, or settling and no flush is
   * scheduled or running.
   * @internal
   */
  static isSettled(): boolean;

  /**
   * Returns a promise that resolves once every pending reaction, in-flight async
   * run, and `afterFlush` callback has completed, including the cascades they
   * schedule. Resolves immediately when already idle.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/flushing#settled settled}
   */
  static settled(): Promise<void>;

  /**
   * Resolves the pending `settled()` promise once the system goes idle.
   * @internal
   */
  static checkSettled(): void;

  /**
   * Logs the source of the currently running reaction for debugging.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/debugging#getsource getSource}
   */
  static getSource(): void;
}

/**
 * Configuration options for creating a new Signal instance.
 * @see {@link https://next.semantic-ui.com/docs/api/reactivity/signal#options Signal Options}
 */
export interface SignalOptions<T> {
  /**
   * Value-protection preset controlling how the stored value is guarded against
   * outside mutation. `'reference'` (default) stores the value by reference.
   * `'clone'` stores and returns defensive copies via `clone`. `'none'` stores
   * by reference and treats every `set()` as a change (event-stream semantics).
   * @default 'reference'
   */
  safety?: 'clone' | 'reference' | 'none';

  /**
   * Determines whether a candidate value differs from the current one. The
   * signal notifies dependents only when this returns `false`. Snapshotted at
   * construction, so reassigning `Signal.equality` later does not affect signals
   * that already exist.
   * @param oldValue - The current value
   * @param newValue - The candidate value
   */
  equality?: (oldValue: T, newValue: T) => boolean;

  /**
   * Produces a copy of a value. Used to insulate stored values when `safety` is
   * `'clone'`, and by `mutate()` to detect in-place changes.
   * @param value - The value to copy
   */
  clone?: <V>(value: V) => V;

  /**
   * Resolves the identity of an array item for the id-based collection helpers
   * (`getItem`, `setItemProperty`, `toggleItemProperty`, `replaceItem`, `removeItem`). Defaults to the
   * first present of `id`, `_id`, `hash`, `key`.
   * @param item - The item to identify
   */
  id?: (item: any) => any;

  /**
   * Seeds the signal's change counter, for aligning `version` with an external
   * store's revision on hydration. Defaults to `0`.
   */
  version?: number;

  /**
   * Debugging context attached to the signal, surfaced in tracing output.
   */
  context?: Record<string, any>;
}

/**
 * A Signal represents a reactive value that automatically triggers updates
 * when modified. It can store any type of value and provides methods for
 * safely mutating that value while maintaining reactivity.
 *
 * Create one with the `signal()` factory or `new Signal()` — both are supported.
 * @see {@link https://next.semantic-ui.com/docs/api/reactivity/signal Signal Documentation}
 */
export class Signal<T> {
  /**
   * Default equality (deep) used by signals that don't supply their own. Set
   * this to change the default for signals created afterward.
   */
  static equality: (oldValue: any, newValue: any) => boolean;

  /**
   * Default clone used by signals that don't supply their own.
   */
  static clone: <V>(value: V) => V;

  /**
   * Default id resolver for the collection helpers. Returns the first present of
   * `id`, `_id`, `hash`, `key`.
   */
  static id: (item: any) => any;

  /**
   * Default safety preset for new signals.
   * @default 'reference'
   */
  static safety: 'clone' | 'reference' | 'none';

  /**
   * Creates a new Signal with an initial value.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/signal#constructor constructor}
   * @param initialValue - The initial value to store in the signal
   * @param options - Configuration options for the signal's behavior
   */
  constructor(initialValue?: T, options?: SignalOptions<T>);

  /**
   * Sets debugging context on the signal, replacing any existing context.
   * Context appears in reactive debugging output and helps trace signal behavior.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/debugging Debugging Reactivity}
   * @param additionalContext - Key-value pairs to store as debugging context
   */
  setContext(additionalContext?: Record<string, any>): void;

  /**
   * Adds debugging context without replacing existing context.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/debugging Debugging Reactivity}
   * @param additionalContext - Key-value pairs to merge into existing context
   */
  addContext(additionalContext?: Record<string, any>): void;

  /**
   * Captures a stack trace into the signal's context. Only does work when stack
   * capture is enabled via `setStackCapture(true)`.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/debugging Debugging Reactivity}
   */
  setTrace(): void;

  /**
   * Gets the current value, establishing a reactive dependency.
   * When accessed within a reactive context (like a Reaction),
   * any changes to this Signal will cause the reactive context to re-run.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/signal#value value}
   */
  get value(): T;

  /**
   * Sets a new value, triggering updates if the value has changed.
   * Notifies all reactive contexts that depend on this Signal to re-run.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/signal#value value}
   */
  set value(
    newValue: T extends null | undefined ? any
      : T extends Array<any> ? Array<Partial<T[number]> & Record<string, any>>
      : T extends object ? Partial<T> & Record<string, any>
      : T,
  );

  /**
   * Gets the current value and establishes a reactive dependency.
   * This is an alias for the `value` getter.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/signal#get get}
   */
  get(): T;

  /**
   * Sets a new value and triggers updates if the value has changed.
   * This is an alias for the `value` setter.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/signal#set set}
   * @param newValue - The new value to set
   */
  set(
    newValue: T extends null | undefined ? any
      : T extends Array<any> ? Array<Partial<T[number]> & Record<string, any>>
      : T extends object ? Partial<T> & Record<string, any>
      : T,
  ): void;

  /**
   * Registers this signal as a dependency in the current reactive context
   * without reading or returning the value. Useful when you need to subscribe
   * to changes without accessing the value.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/signal#depend depend}
   */
  depend(): void;

  /**
   * Force-triggers all subscribers without changing the value. Bypasses the
   * equality check, useful when external code has mutated the stored value
   * in place (under `safety: 'reference'`) and you need to notify dependents.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/signal#notify notify}
   */
  notify(): void;

  /**
   * Returns whether any reactive contexts are currently subscribed to this signal.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/signal#hasdependents hasDependents}
   * @returns `true` if at least one reaction depends on this signal
   */
  hasDependents(): boolean;

  /**
   * Stops the backing reaction of a derived or computed signal. A no-op on a
   * plain signal, which has no producer to tear down.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/signal#stop stop}
   */
  stop(): void;

  /**
   * Returns the current value without establishing a reactive dependency.
   * Under `safety: 'clone'` the returned value is still a defensive copy.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/signal#peek peek}
   */
  peek(): T;

  /**
   * Returns the underlying stored value with no dependency tracking and no
   * clone protection, even under `safety: 'clone'`. This is the live reference,
   * mutating it bypasses change detection. Prefer `peek()` unless you need the
   * exact stored object.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/signal#raw raw}
   */
  raw(): T;

  /**
   * Returns a detached deep copy of the current value, established as a reactive
   * dependency. Always copies, even under `safety: 'reference'` where `get()`
   * returns the live value. Reach for it when you need to sort or mutate the
   * value in place without corrupting the stored object.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/signal#clone clone}
   */
  clone(): T;

  /**
   * Monotonic change counter, bumped on every announced change. Reading it does not
   * subscribe the running reaction. Seedable via the `version` option and freely assignable.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/signal#version version}
   */
  version: number;

  /**
   * Sets the signal's value to undefined.
   * Triggers updates if the value was not already undefined.
   * @see {@link https://next.semantic-ui.com/docs/api/reactivity/signal#clear clear}
   */
  clear(): void;

  /**
   * Mutates the current value in-place via a callback function.
   * If the callback returns a value, that value is set. Otherwise the original
